package keystrokesmod.script.packet.clientbound;
import java.util.Collection; import net.minecraft.network.Packet; import net.minecraft.network.play.server.S3EPacketTeams;
public class S3E extends SPacket { public String name,displayName,prefix,suffix,nametagVisibility; public Collection<String> playerList; public int action,friendlyFlags,color; public S3E(S3EPacketTeams value){super(value);name=value.getName();displayName=value.getDisplayName();prefix=value.getPrefix();suffix=value.getSuffix();nametagVisibility=value.getNameTagVisibility();playerList=value.getPlayers();action=value.getAction();friendlyFlags=value.getFriendlyFlags();color=value.getColor();} public S3E(Packet packet,String name,String displayName,String prefix,String suffix,String visibility,Collection<String> players,int action,int flags,int color){super(packet);this.name=name;this.displayName=displayName;this.prefix=prefix;this.suffix=suffix;nametagVisibility=visibility;playerList=players;this.action=action;friendlyFlags=flags;this.color=color;} }
